    "adultPillar2Desc": "PCOS affects 1 in 5 women of reproductive age. Focusing on blood sugar regulation, low-glycemic Mediterranean meals, strength training, and myo-inositol can substantially restore regular ovulatory cycles.",
    "adultPillar3Title": "Thyroid Metabolism & Energy",
    "adultPillar3Desc": "Thyroid hormones (T3 & T4) govern basal metabolic rate and reproductive stamina. Both hypothyroidism (underactive) and hyperthyroidism (overactive) can alter cycle length, fertility, and body temperature.",
    "adultPillar4Title": "Fertility Awareness & Family Planning",
    "adultPillar4Desc": "Understanding your fertile window (the 5 days leading up to ovulation plus day of ovulation) empowers either natural conception or hormone-free fertility management using basal body temperature (BBT).",
    "adultPillar5Title": "Breast Wellness & Self-Exams",
    "adultPillar5Desc": "Perform monthly breast self-checks 3 to 5 days after your period ends when breast tissue is least tender. Note any new lumps, nipple retraction, skin dimpling, or spontaneous discharge, and report to your physician.",
