    "slot2Title": "மதிய உணவு & 4 டம்ளர் நீர் அருந்துதல்",
    "slot2Desc": "மதிய உணவு சாப்பிட்டீர்களா? இதுவரை 4 டம்ளர் தண்ணீர் குடித்துவிட்டீர்களா?",
    "slot3Title": "மாலை மனநிலை பதிவு & 8 டம்ளர் நீர் இலக்கு",
    "slot3Desc": "மாலை வணக்கம்! உங்கள் மனநிலை எப்படி இருக்கிறது? 8 டம்ளர் முடிச்சிட்டீங்களா?",
    "slot4Title": "இரவு உணவு & மாலை மாத்திரைகள்",
    "slot4Desc": "இரவு உணவு சாப்பிட்டீர்களா? மாலை மாத்திரைகளை எடுத்துக்கொண்டீர்களா?",
    "slot5Title": "இரவு தூக்க நேரம் & கண்களுக்கு ஓய்வு",
    "slot5Desc": "தூங்கும் நேரம்! உங்கள் கண்களுக்கு ஓய்வு கொடுத்து நிம்மதியாக உறங்கவும்.",
    "adminTelemetryTitle": "டிவா சர்வர் & கணினி நிலை விபரங்கள் (அட்மின் கன்சோல்)",
