    "hrvLine1": "✓ தன்னியக்க நரம்பு சமநிலை சிறப்பானது • வேகஸ் நரம்பு செயல்பாடு சீரானது",
    "hrvLine2": "உடற்பயிற்சி மற்றும் தினசரி பணிகளில் இருந்து உடல் விரைவாக புத்துணர்ச்சி பெறுகிறது",
    "bbtLine1": "✓ இருமுனை வெப்ப மாற்றம்: +0.32°C உயர்வு • அண்டவிடுப்பு உறுதிசெய்யப்பட்டது",
    "bbtLine2": "புரோஜெஸ்டிரோன் ஹார்மோன் சுரப்பு ஆரோக்கியமாக உள்ளது • லூட்டியல் 18-ம் நாள்",
    "spo2Line1": "✓ உகந்த தமனி ஆக்சிஜன் செறிவு (95-100% ஆரோக்கியமான வரம்பு)",
    "spo2Line2": "உடல் திசுக்கள் மற்றும் செல்களுக்கு முழுமையான ஆக்சிஜன் சீராக விநியோகிக்கப்படுகிறது",
    "bpLine1": "✓ சிறந்த ரத்த அழுத்த வரம்பு • நாடி அழுத்த வித்தியாசம்: 42 mmHg இயல்பு",
    "bpLine2": "இதய நாளங்களில் அழுத்தம் இன்றி ரத்த ஓட்டம் சீராகப் பாய்கிறது",
