    "stressLine1": "✓ குறைந்த மனஅழுத்த நிலை • சமநிலையான கார்டிசோல் ஹார்மோன் அளவு",
    "stressLine2": "சிம்பதெடிக் நரம்பு அழுத்தம் குறைந்து உடல் ஆழ்ந்த அமைதியில் உள்ளது",
    "gsrLine1": "✓ இயல்பான தோல் மின் கடத்து திறன் • வியர்வை சுரப்பி சமநிலை",
    "gsrLine2": "உணர்ச்சி அமைதி மற்றும் நிலையான உள்ளுணர்வு மனநிலையைக் காட்டுகிறது",
    "sleepLine1": "✓ ஆழ்ந்த தூக்கம்: 2h 15m (29%) • REM கனவுத் தூக்கம்: 1h 45m (23%)",
    "sleepLine2": "லேசான தூக்கம்: 3h 45m (48%) • 88/100 முழுமையான தூக்க தரக் குறியீடு",
    "vo2Line1": "✓ உங்கள் வயதுக்கு ஏற்ற சிறந்த ஏரோபிக் உடற்தகுதி வரம்பு",
    "vo2Line2": "இதய தசை வலிமை மற்றும் நுரையீரல் காற்று கொள்ளளவு சிறப்பானது",
    "calLine1": "✓ உடற்பயிற்சி மற்றும் தொடர் நடைப்பயிற்சியால் எரிக்கப்பட்ட கலோரிகள்",
    "calLine2": "அன்றாட 450 kcal எனர்ஜி இலக்கில் 97% வெற்றிகரமாக எட்டப்பட்டது",
    "stepsLine1": "✓ நடை வேகம்: நிமிடத்திற்கு 104 நடைகள் • தூரம்: 4.0 கி.மீ",
