    "teenTopic1Title": "PMS & మూడ్ స్వింగ్స్",
    "teenTopic1Desc": "పీరియడ్స్‌కు 7-10 రోజుల ముందు ఈస్ట్రోజెన్ మరియు ప్రొజెస్టెరాన్ మార్పుల వల్ల చికాకు, ఆహార కోరికలు కలగవచ్చు. ధ్యానం మరియు నడక మూడ్‌ను స్థిరపరుస్తాయి.",
    "teenTopic2Title": "మొటిమలు & చర్మ హార్మోన్లు",
    "teenTopic2Desc": "యుక్తవయస్సులో హార్మోన్లు చర్మంలో నూనె ఉత్పత్తిని పెంచుతాయి. మొటిమలను గిల్లవద్దు, తేలికపాటి క్లెన్సర్‌తో ముఖం కడుక్కోండి.",
    "teenTopic3Title": "కడుపు నొప్పి & క్రమరహిత సైకిల్స్",
    "teenTopic3Desc": "మొదటి పీరియడ్ తర్వాత సైకిల్ క్రమబద్ధం కావడానికి 2-3 సంవత్సరాలు పట్టవచ్చు. అధిక నొప్పి ఉంటే వైద్యుడిని సంప్రదించండి.",
    "teenTopic4Title": "టీనేజ్ PCOS & థైరాయిడ్ అవగాహన",
    "teenTopic4Desc": "హార్మోన్ల అసమతుల్యత వల్ల అకస్మాత్తుగా బరువు పెరగడం, ముఖంపై అవాంఛిత రోమాలు రావడం జరిగితే మా అసెస్‌మెంట్ చేయండి.",
    "teenTopic5Title": "పోషకాహారం & ఐరన్ బ్యాలెన్స్",
    "teenTopic5Desc": "పీరియడ్స్ సమయంలో ఐరన్ తగ్గుతుంది. పాలకూర, పప్పులు, బెల్లం, మరియు విటమిన్ సి ఉన్న పండ్లను ఆహారంలో చేర్చుకోండి.",
    "teenTopic6Title": "డిజిటల్ ఒత్తిడి & మంచి నిద్ర",
    "teenTopic6Desc": "ఫోన్ బ్లూ లైట్ నిద్ర హార్మోన్ అయిన మెలటోనిన్‌ను తగ్గిస్తుంది. నిద్రకు 45 నిమిషాల ముందు ఫోన్ వాడటం ఆపండి.",
