    "adultPillar2Desc": "PCOS દર ૫ માંથી ૧ મહિલાને અસર કરે છે. રક્ત શર્કરા નિયંત્રણ અને યોગ્ય આહાર માસિક નિયમિત કરે છે.",
    "adultPillar3Title": "થાઇરોઇડ ચયાપચય અને ઊર્જા",
    "adultPillar3Desc": "થાઇરોઇડ હોર્મોન્સ ચયાપચય અને પ્રજનન સહનશક્તિનું નિયમન કરે છે.",
    "adultPillar4Title": "પ્રજનન જાગૃતિ અને કુટુંબ આયોજન",
    "adultPillar4Desc": "ફર્ટાઇલ વિન્ડો સમજીને કુદરતી ગર્ભધારણ અથવા આયોજન સરળ બનાવો.",
    "adultPillar5Title": "સ્તન સ્વાસ્થ્ય અને સ્વ-તપાસ",
    "adultPillar5Desc": "માસિક ધર્મ પછી ૩-૫ દિવસે નિયમિત સ્વ-તપાસ કરો. ફેરફાર જણાય તો ડૉક્ટરનો સંપર્ક કરો.",
    "adultPillar6Title": "ગર્ભાશય ગ્રીવા સ્વાસ્થ્ય અને પેપ ટેસ્ટ",
    "adultPillar6Desc": "૨૧ થી ૬૫ વર્ષ સુધી નિયમિત પેપ સ્મીયર તપાસ સ્વાસ્થ્ય માટે હિતાવહ છે.",
    "adultPillar7Title": "ગર્ભનિરોધક અને માહિતગાર સંમતિ",
