    "teenTopic1Title": "PMS और मूड स्विंग्स",
    "teenTopic1Desc": "पीरियड्स से 7-10 दिन पहले हार्मोनल बदलावों के कारण चिड़चिड़ापन या उदासी हो सकती है। गहरी सांसें और टहलना मन को शांत करता है।",
    "teenTopic2Title": "मुंहासे और त्वचा हार्मोन",
    "teenTopic2Desc": "किशोरावस्था में हार्मोन तेल उत्पादन बढ़ाते हैं। मुंहासों को फोड़ें नहीं, हल्के क्लींजर से दिन में दो बार चेहरा धोएं।",
    "teenTopic3Title": "पीरियड दर्द और अनियमित चक्र",
    "teenTopic3Desc": "पहले पीरियड के बाद चक्र को नियमित होने में 2-3 साल लग सकते हैं। यदि अत्यधिक दर्द हो तो डॉक्टर से परामर्श लें।",
    "teenTopic4Title": "PCOS और थायरॉयड जागरूकता",
    "teenTopic4Desc": "अचानक वजन बढ़ना या चेहरे पर घने बाल आना हार्मोनल असंतुलन का संकेत हो सकता है। हमारी स्वास्थ्य जांच लें।",
    "teenTopic5Title": "पोषण और आयरन संतुलन",
    "teenTopic5Desc": "पीरियड्स के दौरान आयरन की कमी हो सकती है। पालक, दालें, गुड़ और विटामिन सी युक्त फल आहार में शामिल करें।",
    "teenTopic6Title": "डिजिटल तनाव और गहरी नींद",
