    "teenHubTitle": "കൗമാര ആരോഗ്യം, ഹോർമോണുകൾ & ആത്മവിശ്വാസം",
    "teenHubSub": "ആർത്തവം, ചർമ്മം, മാനസികാരോഗ്യം എന്നിവയ്ക്കുള്ള ശാസ്ത്രീയ വിവരങ്ങൾ.",
    "teenHubBadge": "കൗമാര ആരോഗ്യ കേന്ദ്രം (13–19 വയസ്സ്)",
    "teenDisclaimer": "ഈ വിഭാഗം കൗമാരക്കാർക്കുള്ള ആരോഗ്യ വിവരങ്ങൾ നൽകുന്നു. ഡോക്ടറുടെ ഉപദേശത്തിന് പകരമല്ല.",
    "teenTopic1Title": "PMS ഉം മാനസികാവസ്ഥയും",
    "teenTopic1Desc": "ആർത്തവത്തിന് 7-10 ദിവസം മുമ്പ് ഹോർമോൺ വ്യതിയാനങ്ങൾ മൂഡ് മാറ്റങ്ങൾക്ക് കാരണമാകാം. നടത്തവും ധ്യാനവും ഗുണം ചെയ്യും.",
    "teenTopic2Title": "മുഖക്കുരുവും ചർമ്മ ഹോർമോണുകളും",
    "teenTopic2Desc": "കൗമാരത്തിൽ എണ്ണമയം കൂടും. മുഖക്കുരു പൊട്ടിക്കരുത്, വീര്യം കുറഞ്ഞ ഫേസ്‌വാഷ് ഉപയോഗിക്കുക.",
    "teenTopic3Title": "ആർത്തവ വേദനയും ക്രമം തെറ്റലും",
    "teenTopic3Desc": "ആദ്യ ആർത്തവത്തിന് ശേഷം ക്രമമാകാൻ 2-3 വർഷം എടുക്കാം. കഠിനമായ വേദനയുണ്ടെങ്കിൽ ഡോക്ടറെ കാണുക.",
    "teenTopic4Title": "PCOS ഉം തൈറോയ്ഡ് അവബോധവും",
    "teenTopic4Desc": "പെട്ടെന്ന് ഭാരം കൂടുകയോ അനാവശ്യ രോമവളർച്ചയോ ഉണ്ടായാൽ പരിശോധന നടത്തുക.",
    "teenTopic5Title": "പോഷകാഹാരവും ഇരുമ്പിന്റെ അളവും",
    "teenTopic5Desc": "ആർത്തവസമയത്ത് ഇരുമ്പ് നഷ്ടപ്പെടുന്നു. ചീര, പയർവർഗ്ഗങ്ങൾ, ശർക്കര എന്നിവ ഭക്ഷണത്തിൽ ഉൾപ്പെടുത്തുക.",
    "teenTopic6Title": "ഡിജിറ്റൽ സ്ട്രെസ്സും ഉറക്കവും",
    "teenTopic6Desc": "ഫോൺ വെളിച്ചം ഉറക്കത്തെ ബാധിക്കും. ഉറങ്ങുന്നതിന് 45 മിനിറ്റ് മുമ്പ് ഫോൺ മാറ്റിവെക്കുക.",
    "age12HubTitle": "കൗമാരവും ആർത്തവവും മനസ്സിലാക്കാം",
