    "adultPillar1Desc": "Your menstrual cycle is considered the \"fifth vital sign\". Tracking follicular phase energy, ovulatory cervical mucus changes, and luteal phase patterns gives deep visibility into metabolic resilience.",
    "adultPillar2Title": "PCOS / PCOD & Insulin Sensitivity",
    "adultPillar2Desc": "PCOS affects 1 in 5 women of reproductive age. Focusing on blood sugar regulation, low-glycemic Mediterranean meals, strength training, and myo-inositol can substantially restore regular ovulatory cycles.",
    "adultPillar3Title": "Thyroid Metabolism & Energy",
    "adultPillar3Desc": "Thyroid hormones (T3 & T4) govern basal metabolic rate and reproductive stamina. Both hypothyroidism (underactive) and hyperthyroidism (overactive) can alter cycle length, fertility, and body temperature.",
    "adultPillar4Title": "Fertility Awareness & Family Planning",
    "adultPillar4Desc": "Understanding your fertile window (the 5 days leading up to ovulation plus day of ovulation) empowers either natural conception or hormone-free fertility management using basal body temperature (BBT).",
    "adultPillar5Title": "Breast Wellness & Self-Exams",
    "adultPillar5Desc": "Perform monthly breast self-checks 3 to 5 days after your period ends when breast tissue is least tender. Note any new lumps, nipple retraction, skin dimpling, or spontaneous discharge, and report to your physician.",
    "adultPillar6Title": "Cervical Health & Pap Screening",
    "adultPillar6Desc": "Routine Pap smears and HPV screenings from age 21 to 65 are highly effective at detecting precancerous cervical cell changes early. Discuss HPV vaccination and routine smear intervals with your doctor.",
    "adultPillar7Title": "Contraception & Informed Consent",
    "adultPillar7Desc": "Comprehensive education on barrier methods, oral contraceptives, hormonal and copper IUDs, emergency contraception, and mutual enthusiastic consent in sexual relationships.",
    "adultPillar8Title": "Mental Health, Burnout & Perimenopause",
    "adultPillar8Desc": "Addressing high-stress cortisol spikes, career burnout, sleep disruption, and the hormonal transitions of perimenopause (hot flashes, brain fog, sleep shifts) through mindful evidence-based strategies.",
    "teenHubTitle": "Teen Health, Hormones & Confidence",
    "teenHubSub": "Empowering science-backed guidance for your cycle, skin, emotions, and academic wellness.",
    "teenHubBadge": "Teen Wellness Hub (Ages 13–19)",
    "teenDisclaimer": "This section provides educational wellness information for teenagers. It does not replace medical consultation with a pediatrician or gynecologist.",
    "teenTopic1Title": "PMS & Mood Navigations",
    "teenTopic1Desc": "Premenstrual Syndrome (PMS) occurs 7-10 days before your period due to shifts in estrogen and progesterone. You might notice irritability, food cravings, or weepiness. Deep breathing, journaling, and mindful walks help ground your mood.",
    "teenTopic2Title": "Acne & Skin Hormones",
    "teenTopic2Desc": "Surging androgens increase sebum (skin oil) during teenage years. Wash with a gentle, non-comedogenic salicylic acid cleanser, avoid popping pimples (which causes scarring), and never sleep with makeup on.",
    "teenTopic3Title": "Period Pain & Irregular Cycles",
    "teenTopic3Desc": "It takes up to 2-3 years for cycles to regulate after your first period. Occasional variation is normal, but if periods are absent for over 90 days, or cramps cause you to miss school, talk with a healthcare professional.",
    "teenTopic4Title": "Teen PCOS & Thyroid Awareness",
    "teenTopic4Desc": "PCOS involves higher androgens and irregular ovulation; thyroid disorders affect metabolism and energy. If you notice sudden unexplained weight shifts, excessive facial hair, or chronic exhaustion, take our wellness checks.",
    "teenTopic5Title": "Nutrition & Iron Balance",
    "teenTopic5Desc": "During your period, you lose iron. Replenish with spinach, lentils, jaggery, beetroot, and Vitamin C (amla, oranges, lemons) to enhance iron absorption and prevent teenage fatigue and anemia.",
    "teenTopic6Title": "Digital Stress & Restful Sleep",
    "teenTopic6Desc": "Blue light from phones suppresses melatonin, the sleep hormone. Try a digital curfew 45 minutes before bedtime to ensure 8-9 hours of restorative sleep essential for hormonal harmony.",
